+    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
+        index += 1;
+    }
+
+    let mut sign = 1i64;
+    if index < bytes.len() {
+        match bytes[index] {
+            b'+' => index += 1,
+            b'-' => {
