        if let Some(scheme_end) = input.find("://") {
            let scheme = lowercase_ascii(&input[..scheme_end]);
            let remainder = &input[scheme_end + 3..];
            let (authority_raw, tail) = split_authority(remainder);
            let parsed_authority = parse_authority(authority_raw);
            let ParsedTail {
                path,
                query,
                fragment,
            } = parse_tail(tail);

            return Self {
                scheme,
                authority: parsed_authority.authority,
                port: parsed_authority.port,
                valid: parsed_authority.host_present || !path.is_empty(),
                path,
                query,
                fragment,
            };
        }

        let ParsedTail {
            path,
            query,
            fragment,
        } = parse_tail(input);

        Self {
            scheme: String::new(),
            authority: String::new(),
            port: -1,
            valid: !path.is_empty(),
            path,
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}

fn lowercase_ascii(input: &str) -> String {
    input.chars().map(|ch| ch.to_ascii_lowercase()).collect()
}

fn split_authority(input: &str) -> (&str, &str) {
    for (index, ch) in input.char_indices() {
        if matches!(ch, '/' | '?' | '#') {
            return (&input[..index], &input[index..]);
        }
    }

    (input, "")
}

