pub fn parse_port(input: &str) -> Option<i32> {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let digits_start = index;
    let mut value = 0i64;

    // Match std::stoi-style parsing: consume a signed decimal prefix and ignore
    // any trailing non-numeric suffix.
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = value
            .checked_mul(10)?
            .checked_add((bytes[index] - b'0') as i64)?;
        index += 1;
    }

    if index == digits_start {
        return None;
    }

    let signed = value.checked_mul(sign)?;
    if signed < i32::MIN as i64 || signed > i32::MAX as i64 {
        return None;
    }

    Some(signed as i32)
}

#[cfg(test)]
mod tests {
    use super::parse_port;

    #[test]
    fn parses_signed_prefix_with_suffix() {
        assert_eq!(parse_port(" +80extra"), Some(80));
        assert_eq!(parse_port(" -1x"), Some(-1));
    }

    #[test]
    fn rejects_non_numeric_prefixes_and_overflow() {
        assert_eq!(parse_port(""), None);
        assert_eq!(parse_port("+"), None);
        assert_eq!(parse_port("abc"), None);
        assert_eq!(parse_port("2147483648"), None);
    }
}

