#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedTail {
    pub path: String,
    pub query: String,
    pub fragment: String,
}

pub fn parse_tail(input: &str) -> ParsedTail {
    if input.is_empty() {
        return ParsedTail {
            path: String::new(),
            query: String::new(),
            fragment: String::new(),
        };
    }

    let bytes = input.as_bytes();
    match bytes[0] {
        b'?' => parse_query_and_fragment(&input[1..]),
        b'#' => ParsedTail {
            path: String::new(),
            query: String::new(),
            fragment: input[1..].to_string(),
        },
        _ => parse_path_query_and_fragment(input),
    }
}

fn parse_query_and_fragment(input: &str) -> ParsedTail {
    if let Some(hash_index) = input.find('#') {
        ParsedTail {
            path: String::new(),
            query: input[..hash_index].to_string(),
            fragment: input[hash_index + 1..].to_string(),
        }
    } else {
        ParsedTail {
            path: String::new(),
            query: input.to_string(),
            fragment: String::new(),
        }
    }
}

fn parse_path_query_and_fragment(input: &str) -> ParsedTail {
    if let Some(query_index) = input.find('?') {
        let path = input[..query_index].to_string();
        let remainder = &input[query_index + 1..];

        if let Some(hash_index) = remainder.find('#') {
            ParsedTail {
                path,
                query: remainder[..hash_index].to_string(),
                fragment: remainder[hash_index + 1..].to_string(),
            }
        } else {
            ParsedTail {
                path,
                query: remainder.to_string(),
                fragment: String::new(),
            }
        }
    } else if let Some(hash_index) = input.find('#') {
        ParsedTail {
            path: input[..hash_index].to_string(),
            query: String::new(),
            fragment: input[hash_index + 1..].to_string(),
        }
    } else {
        ParsedTail {
            path: input.to_string(),
            query: String::new(),
            fragment: String::new(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::parse_tail;

    #[test]
    fn parses_path_with_query_and_fragment() {
        let parsed = parse_tail("/path?x=1#frag");

        assert_eq!(parsed.path, "/path");
        assert_eq!(parsed.query, "x=1");
        assert_eq!(parsed.fragment, "frag");
    }

    #[test]
    fn keeps_query_marker_inside_fragment_when_hash_comes_first() {
        let parsed = parse_tail("#frag?x=1");

        assert_eq!(parsed.path, "");
        assert_eq!(parsed.query, "");
        assert_eq!(parsed.fragment, "frag?x=1");
    }
}

